    constructor(options) {
      super({
        state: 'loading',
        tileGrid: null,
        projection: options.projection !== undefined ? options.projection : null,
        opaque: options.opaque,
        transition: options.transition,
        interpolate: options.interpolate !== false,
        wrapX: options.wrapX,
      });
>>>>>>> REPLACE
```

With this change you can now pass your COG’s UTM projection into GeoTIFF:

```js
const source = new ol.source.GeoTIFF({
  sources: [
    {
      url: '…TCI.tif'
    }
  ],
  projection: cogProj
});
```

and WebGLTileLayer will see the correct native CRS and perform the reprojection to your view’s CRS automatically.
